                //   而这行代码把页面上所有嵌套的玻璃后代全掐了（「东一块西一块」的真凶之一）。
                if (parseFloat(cs.opacity) < 1) return true;
                if (cs.maskImage && cs.maskImage !== 'none') return true;
                if (cs.webkitMaskImage && cs.webkitMaskImage !== 'none') return true;
