a.__bomToken = 0;   // 还没切过歌，和初始的 loadToken 对齐\n        /* ★ 只要真的开始播了，就把副标题恢复成「n / 总数 · 歌手」。\n           之前各种提示（\"播不了…\"、\"正在获取音频 100%\"）是过程状态，播放一旦成功\n           就该消失 —— 否则会出现「正在播、底下却写着播不了」。 */\n        a.addEventListener('play', function () {\n            syncPlaying(true);\n            restoreSubTitle();\n            userPaused = false;   // 又播起来了，之前的「用户暂停」作废\n            /* 真的播起来了：连续失败的账清零，并且取消掉还没执行的自动跳过 */\n            cancelPendingSkip();\n            autoSkipCount = 0;\n            lastAutoSkipSong = '';\n            recentFailed = {};\n        });\n        a.addEventListener('pause', function () {\n            /* ★ 先记意图、先落盘，再做 UI。\n               反过来做的话，syncPlaying 里任何一个子调用抛错都会把后面这步截断，\n               结果就是「暂停了但状态还写着在播」，下次进页面照样自动播。 */\n            if (!unloading) {\n                userPaused = true;\n                saveResume();\n            }\n            syncPlaying(false);\n        });\n        a.addEventListener('error', function () {\n            /* 主动清 src（删歌 / 停止）时也会冒一个 error，别报给用户 */\n            if (!a.getAttribute('src')) return;\n            var code = a.error ? a.error.code : 0;\n            /* ★ 切歌时浏览器会 abort 上一首，这会触发一次 error(code 1)。\n               那不是故障 —— 以前没挡掉，结果刚切到的这首被判成「播不了」直接跳过\n               （用户反馈「他跳过了能播的」）。code 1 直接忽略；\n               再用 token 挡掉上一首迟到的 error。 */\n            if (code === 1) return;\n            if (a.__bomToken !== loadToken) return;\n            var map = {\n                1: '加载被中断',\n                2: '网络错误（链接打不开）',\n                3: '解码失败（可能不是音频）',\n                4: '格式不支持或链接无效'\n            };\n            /* 浏览器对「被 CSP 拦掉」给的原文是\n               \"MEDIA_ELEMENT_ERROR: Media load rejected by URL safety check\"，\n               跟真正的格式错误混在一个 code 里，所以单独判一下。 */\n            var detail = (a.error && a.error.message) || '';\n            var blocked = /URL safety check|Content Security Policy/i.test(detail);\n            log('error', '音频错误', {\n                code: code, msg: map[code] || '未知', blocked: blocked,\n